  var SIG = { 5: 'Urgent', 4: 'High', 3: 'Note', 2: 'Minor', 1: 'Noise' };
  var FILTERS = [['all', 'All', function () { return true; }], ['alerts', 'Alerts', function (c) { return c.significance >= D.settings.alert_threshold; }], ['prices', 'Prices', function (c) { return /price/.test(c.kind); }], ['products', 'Products and stock', function (c) { return /product|stock/.test(c.kind); }], ['promo', 'Promotions', function (c) { return c.kind === 'promotion' || c.kind === 'messaging'; }], ['news', 'Hiring and news', function (c) { return c.kind === 'hiring' || c.kind === 'news'; }], ['issues', 'Page issues', function (c) { return c.kind === 'layout_warning' || c.kind === 'fetch_failed'; }]];
  function ago(iso) { if (!iso) return 'never'; var m = Math.round((NOW - new Date(iso)) / 6e4); if (m < 1) return 'just now'; if (m < 60) return m + ' min ago'; var h = Math.round(m / 60); if (h < 24) return h + ' h ago'; var d = Math.round(h / 24); return d === 1 ? 'yesterday' : d + ' days ago'; }
  function dshort(iso) { return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }); }

